// #95ffe2 API נתוני מגמות ודשבורד — без входа (только publishable key, без JWT пользователя). Только чтение, без браузера.
// Гостя через сайт не используем: сайт сразу создаёт анонимного пользователя Supabase (лишние аккаунты).
import { test, expect } from '@playwright/test';
import { SUPABASE_URL, sbKey } from './_trends';

test('daily_totals без входа → 401 permission denied #95ffe2 @desktop @prod-safe', async ({ request }) => {
  // AC8: требуется вошедший пользователь.
  const key = sbKey();
  const r = await request.get(`${SUPABASE_URL}/rest/v1/daily_totals?select=local_date,kcal&limit=1`, {
    headers: { apikey: key, Authorization: `Bearer ${key}` },
  });
  expect(r.status()).toBe(401);
  const body = await r.json();
  expect(body.message).toContain('permission denied for view daily_totals');
});
